const trigger = $input.first().json || {};
let query = String(trigger.query || trigger.user_query || trigger.username || trigger.contact_name || '').trim();
let conversation_id = trigger.conversation_id ? parseInt(trigger.conversation_id) : 0;
let account_id = trigger.account_id ? parseInt(trigger.account_id) : 1;

if (query.startsWith('{') && query.endsWith('}')) {
  try {
    const qObj = JSON.parse(query);
    if (qObj.query) query = String(qObj.query).trim();
    if (qObj.username) query = String(qObj.username).trim();
    if (qObj.contact_name) query = String(qObj.contact_name).trim();
    if (qObj.conversation_id) conversation_id = parseInt(qObj.conversation_id);
  } catch(e) {}
}

query = query.replace(/^["']|["']$/g, '').trim();

return [{
  json: {
    raw_query: query,
    search_term: query,
    conversation_id: conversation_id,
    account_id: account_id
  }
}];

const rows = $input.all();
const prepData = $('Code').first().json || {};
const searchTerm = String(prepData.search_term || '').trim();
const convId = prepData.conversation_id || 0;
const accId = prepData.account_id || 1;

if (!searchTerm && rows.length === 0) {
  return [{
    json: {
      status: 'not_found',
      found: false,
      message: 'No se pudo realizar la búsqueda o el término de búsqueda está vacío.',
      instructions_for_ai: "No se encontraron credenciales en el sistema. REGLA ESTRICTA: Indica al cliente amablemente que por favor utilice las credenciales y URLs de servidor con las que ya cuenta / se le suministraron al momento de su activación. Si no las tiene o requiere asistencia, transfiérelo con soporte humano."
    }
  }];
}

const normalize = (str) => String(str || '')
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/\s+/g, ' ')
  .trim();

const searchNorm = normalize(searchTerm);
const searchDigits = searchTerm.replace(/\D/g, '');

const getField = (obj, regex) => {
  if (!obj) return '';
  for (const k of Object.keys(obj)) {
    if (regex.test(k.trim())) {
      const v = obj[k];
      if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
    }
  }
  return '';
};

let bestMatch = null;
let bestScore = 0;

for (const r of rows) {
  const row = r.json || {};
  const usuario = getField(row, /^(usuario|username|user)/i);
  const clave = getField(row, /^(clave|password|pass)/i);
  const idVal = getField(row, /^(id|sub_id|subscription_id)/i);
  const nombre = getField(row, /^(nombre|name|cliente)/i);
  const apellido = getField(row, /^(apellido|last_name)/i);
  const tel = getField(row, /^(tel|phone|cel|movil|whats)/i);
  const email = getField(row, /^(email|correo)/i);
  const vence = getField(row, /^(vence|expire)/i);

  const fullNombre = [nombre, apellido].filter(Boolean).join(' ');
  const userNorm = normalize(usuario);
  const nombreNorm = normalize(fullNombre);
  const emailNorm = normalize(email);
  const telDigits = tel.replace(/\D/g, '');

  let score = 0;

  // 1. Exact match on Usuario (highest priority)
  if (userNorm && userNorm === searchNorm) {
    score = 100;
  } else if (searchDigits && userNorm && userNorm === searchDigits) {
    score = 95;
  }
  // 2. Phone match
  else if (searchDigits.length >= 7 && telDigits && (telDigits.endsWith(searchDigits) || searchDigits.endsWith(telDigits))) {
    score = 80;
  }
  // 3. Email match
  else if (emailNorm && emailNorm === searchNorm) {
    score = 75;
  }
  // 4. Full Name match
  else if (nombreNorm && (nombreNorm === searchNorm || nombreNorm.includes(searchNorm) || searchNorm.includes(nombreNorm))) {
    score = 60;
  }

  if (score > bestScore) {
    bestScore = score;
    bestMatch = {
      row_data: row,
      id: idVal,
      usuario: usuario,
      clave: clave,
      nombre: fullNombre,
      telefono: tel,
      email: email,
      vence: vence
    };
  }
}

// Consult Mega OTT API for live dynamic DNS links and account verification
const megaToken = '1655|Uk2GI2EUH0v8NIcUFjGwLeKLlp14bVmEi2rcGSuJ48ec8236';
const megaApiBase = 'https://megaott.net/api/v1';

let liveUser = bestMatch ? bestMatch.usuario : '';
let livePass = bestMatch ? bestMatch.clave : '';
let dnsGeneral = '';
let dnsSmarters = '';
let expireDate = bestMatch ? bestMatch.vence : '';
let matchedSubId = bestMatch ? bestMatch.id : null;

// 1. Direct ID fetch from Mega API if available
if (matchedSubId && /^\d+$/.test(matchedSubId)) {
  try {
    const apiRes = await this.helpers.httpRequest({
      method: 'GET',
      url: `${megaApiBase}/subscriptions/${matchedSubId}`,
      headers: {
        'Authorization': `Bearer ${megaToken}`,
        'Accept': 'application/json',
        'User-Agent': 'Mozilla/5.0'
      },
      json: true
    });

    const sub = apiRes && apiRes.data ? apiRes.data : (apiRes || {});
    if (sub.username) liveUser = sub.username;
    if (sub.password) livePass = sub.password;
    if (sub.dns_link) dnsGeneral = sub.dns_link;
    if (sub.dns_link_for_samsung_lg) dnsSmarters = sub.dns_link_for_samsung_lg;
    if (sub.expiring_at || sub.expire_date) expireDate = sub.expiring_at || sub.expire_date;
  } catch (e) {}
}

// 2. If DNS is not yet found from Mega API, search Mega OTT API directly across pages
if (!dnsGeneral || !dnsSmarters) {
  const targetUsers = [
    liveUser,
    searchTerm,
    bestMatch ? bestMatch.usuario : '',
    bestMatch ? bestMatch.nombre : ''
  ].filter(Boolean).map(normalize);

  for (let page = 1; page <= 5; page++) {
    try {
      const apiList = await this.helpers.httpRequest({
        method: 'GET',
        url: `${megaApiBase}/subscriptions?per_page=100&page=${page}`,
        headers: {
          'Authorization': `Bearer ${megaToken}`,
          'Accept': 'application/json',
          'User-Agent': 'Mozilla/5.0'
        },
        json: true
      });
      const items = apiList && apiList.data ? apiList.data : [];
      if (!Array.isArray(items) || items.length === 0) break;

      for (const sub of items) {
        const uNorm = normalize(sub.username);
        const noteNorm = normalize(sub.note);
        const phoneDigits = String(sub.whatsapp_telegram || '').replace(/\D/g, '');
        const isCompanyPhone = phoneDigits.includes('13059861096') || phoneDigits.includes('573009476271');

        // Check username match (highest priority)
        const isUserMatch = targetUsers.some(t => t && t.length >= 3 && (uNorm === t || (uNorm.length >= 4 && (uNorm.includes(t) || t.includes(uNorm)))));

        // Check note match (must be non-empty and at least 4 chars)
        const isNoteMatch = noteNorm && noteNorm.length >= 4 && targetUsers.some(t => t && t.length >= 4 && (noteNorm === t || noteNorm.includes(t) || t.includes(noteNorm)));

        // Check customer phone match (ignore company support numbers)
        const isPhoneMatch = !isCompanyPhone && searchDigits.length >= 7 && phoneDigits.length >= 7 && (phoneDigits.endsWith(searchDigits) || searchDigits.endsWith(phoneDigits));

        if (isUserMatch || isNoteMatch || isPhoneMatch) {
          matchedSubId = sub.id;
          if (sub.username) liveUser = sub.username;
          if (sub.password) livePass = sub.password;
          if (sub.dns_link) dnsGeneral = sub.dns_link;
          if (sub.dns_link_for_samsung_lg) dnsSmarters = sub.dns_link_for_samsung_lg;
          if (sub.expiring_at || sub.expire_date) expireDate = sub.expiring_at || sub.expire_date;
          break;
        }
      }
      if (dnsGeneral && dnsSmarters) break;
      if (!apiList.next_page_url) break;
    } catch (e) {
      break;
    }
  }
}

if (!liveUser || (!dnsGeneral && !bestMatch)) {
  return [{
    json: {
      status: 'not_found',
      found: false,
      message: `No se encontraron credenciales en el sistema ni en la API de Mega para "${searchTerm}".`,
      instructions_for_ai: "No se encontraron credenciales en el sistema para este usuario. REGLA ESTRICTA: Indica al cliente amablemente que por favor utilice las credenciales y URLs de servidor con las que ya cuenta / se le suministraron al momento de su activación. Si no las tiene o requiere asistencia, transfiérelo con soporte humano."
    }
  }];
}

// Register private note in Chatwoot if conversation_id is available
if (convId) {
  try {
    const chatwootToken = 'Dk8XKwvnkGx79rjiL5cLdVZd';
    const noteContent = `🤖 **CREDENCIALES RECUPERADAS (Mega / TotalTv USA)**\n• Cliente: ${(bestMatch && bestMatch.nombre) ? bestMatch.nombre : searchTerm}\n• Usuario: ${liveUser}\n• Contraseña: ${livePass}\n• 🌐 DNS General: ${dnsGeneral || 'N/A'}\n• 📺 DNS Smarters: ${dnsSmarters || 'N/A'}\n• Vence: ${expireDate || 'N/A'}`;

    await this.helpers.httpRequest({
      method: 'POST',
      url: `https://chatwoot.ac4.club/api/v1/accounts/${accId}/conversations/${convId}/messages`,
      headers: {
        'api_access_token': chatwootToken,
        'Content-Type': 'application/json',
        'User-Agent': 'Mozilla/5.0'
      },
      body: {
        content: noteContent,
        private: true
      },
      json: true
    });
  } catch (e) {}
}

return [{
  json: {
    status: 'found',
    found: true,
    username: liveUser,
    password: livePass,
    dns_general: dnsGeneral,
    dns_smarters: dnsSmarters,
    expire_date: expireDate,
    customer_name: (bestMatch && bestMatch.nombre) ? bestMatch.nombre : searchTerm,
    instructions_for_ai: "Entrega al cliente sus credenciales y URLs exactos recuperados de la API de Mega: Usuario, Contraseña, 🌐 DNS General (para SmartOne, IBO Player, XCIPTV, etc.) y 📺 DNS Smarters (para Smarters Player Lite, IPTV Smarters Pro). REGLA ESTRICTA: NO inventes otros URLs ni digas 'most apps'."
  }
}];

const item = $input.first().json || {};

if (item.found) {
  return [{
    json: {
      status: 'found',
      username: item.username,
      password: item.password,
      dns_general: item.dns_general,
      dns_smarters: item.dns_smarters,
      expire_date: item.expire_date,
      customer_name: item.customer_name,
      instructions_for_ai: item.instructions_for_ai
    }
  }];
} else {
  return [{
    json: {
      status: 'not_found',
      message: item.message || 'No se encontraron credenciales en el sistema.',
      instructions_for_ai: item.instructions_for_ai
    }
  }];
}
